insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_142'
from (values
('127.889.d.1.A',3,'At a powerplant job fair, Lena compares working at an engine overhaul shop, a regional airline and running her own engine repair business. She is:','["identifying and comparing employment opportunities, including entrepreneurship", "picking randomly", "ignoring careers", "avoiding jobs"]'::jsonb,0,'Engine careers.','original'),
('127.889.d.1.A',4,'A technician who opens her own engine rebuild shop is taking on the role of:','["a pilot", "an entrepreneur who owns the business", "a customer", "an employee only"]'::jsonb,1,'Owner role.','original'),
('127.889.d.1.B',3,'On a engine swap, Jorge hands tools to his partner and calls out torque values as the partner tightens. He is showing how to:','["skip tasks", "work alone", "contribute and collaborate as an effective member of a team", "slow the crew"]'::jsonb,2,'Engine team.','original'),
('127.889.d.1.B',4,'A two-person engine hoist job goes smoothly when each person:','["guesses", "works silently", "avoids the other", "knows their role and communicates clearly"]'::jsonb,3,'Clear roles.','original'),
('127.889.d.1.C',3,'A powerplant student learns that a technician must never sign for work on a magneto that she did not personally verify. She is identifying:','["individual ethical and legal behavior standards according to professional and industry standards", "no standards", "shop humor", "optional rules"]'::jsonb,0,'Legal conduct.','original'),
('127.889.d.1.C',4,'Signing a logbook entry for work you did not do is:','["a shortcut", "a violation of ethical and legal standards", "acceptable", "common practice"]'::jsonb,1,'False sign-off.','original'),
('127.889.d.1.D',3,'A class researches why engine maintenance manuals and service bulletins are in English and why technicians must read them accurately. They are discussing:','["a local custom", "a style choice", "the impact of English language proficiency requirements on aviation", "no impact"]'::jsonb,2,'English requirement.','original'),
('127.889.d.1.D',4,'A misread torque value in an engine manual could lead to:','["a perfect assembly", "an easier repair", "a faster job", "a loose or overstressed fastener"]'::jsonb,3,'Misread data.','original'),
('127.889.d.1.E',3,'A shop talk covers fatigue, distraction, stress and rushing as causes of errors in engine work. They are identifying:','["human factors that may impact health and safety in a worksite", "tool brands", "weather factors", "no factors"]'::jsonb,0,'Human factors.','original'),
('127.889.d.1.E',4,'Working a double shift without rest increases the risk of:','["better focus", "mistakes and injury", "extra safety", "fewer errors"]'::jsonb,1,'Fatigue.','original'),
('127.889.d.1.F',3,'A lead requires a second technician to inspect a safety-wired propeller bolt, because even experts miss things. This explains:','["paint issues", "no role", "the role of human factors in maintaining health and safety in the workplace", "tool failure"]'::jsonb,2,'Error checks.','original'),
('127.889.d.1.F',4,'Checklists and independent inspections are used mainly to:','["hide mistakes", "avoid training", "slow the work", "catch errors caused by human factors"]'::jsonb,3,'Safeguards.','original'),
('127.889.d.1.G',3,'A technician stops a job when she realizes she skipped a step, even though the plane is due out in an hour. This shows how:','["an employee''s personal responsibility attitudes can affect health and safety", "pressure removes responsibility", "schedules come first", "safety is optional"]'::jsonb,0,'Own the stop.','original'),
('127.889.d.1.G',4,'A responsible technician who finds her own error should:','["hide it", "report it and correct it before release", "blame someone", "wait to see"]'::jsonb,1,'Admit errors.','original'),
('127.889.d.1.H',3,'In a role-play, a customer asks a student to sign off an engine run-up that was never done. The student refuses and explains why. She is applying:','["rule breaking", "avoidance", "reasoning skills to simulated workplace situations in order to make ethical decisions", "poor judgment"]'::jsonb,2,'Ethics role-play.','original'),
('127.889.d.1.H',4,'When asked to falsify a record, an ethical technician should:','["ignore it", "accept payment", "comply", "decline and document the request"]'::jsonb,3,'Say no.','original'),
('127.889.d.1.I',3,'A shop requires closed-toe shoes, safety glasses and tied-back hair near running engines. These are:','["industry standards related to employee appearance and health habits", "decor", "random rules", "optional style"]'::jsonb,0,'Shop standards.','original'),
('127.889.d.1.I',4,'Long loose hair around a rotating propeller or shaft is hazardous because it can:','["stay clean", "get caught and pull the person in", "look better", "blow away"]'::jsonb,1,'Hair hazard.','original'),
('127.889.d.1.J',3,'Priya writes a clear work order summary and then walks the customer through the engine findings out loud. She is practicing:','["no communication", "unclear notes", "effective written and oral communication skills", "guessing"]'::jsonb,2,'Communication.','original'),
('127.889.d.1.J',4,'A work order for an engine repair should clearly state:','["only a name", "a joke", "only the date", "the problem, the work done and the parts used"]'::jsonb,3,'Work order.','original'),
('127.889.d.1.K',3,'A senior technician explains the start-up checklist while the new hire repeats the key steps back. This shows:','["effective listening skills", "ignoring", "interrupting", "poor listening"]'::jsonb,0,'Listening.','original'),
('127.889.d.1.K',4,'Good listeners confirm understanding by:','["staying silent", "asking questions and restating what they heard", "looking away", "walking off"]'::jsonb,1,'Confirm.','original'),
('127.889.d.1.L',3,'A technician learns that ''must'' in an FAA document means an action is required, while ''should'' is a recommendation. She is applying:','["random terms", "slang", "FAA standard terms that have specific expectations for performance", "casual words"]'::jsonb,2,'FAA terms.','original'),
('127.889.d.1.L',4,'In FAA regulations, ''may not'' means the action is:','["optional", "suggested", "encouraged", "prohibited"]'::jsonb,3,'May not.','original'),
('127.889.d.2.A',3,'A student labels the cylinders, pistons, crankshaft and valves of an engine and compares inline, radial and horizontally opposed layouts. She is:','["identifying the components and types of reciprocating internal combustion aircraft engines", "labeling tires", "labeling lights", "labeling seats"]'::jsonb,0,'Piston engines.','original'),
('127.889.d.2.A',4,'Most small general aviation airplanes use a:','["radial only", "horizontally opposed engine", "rotary only", "steam engine"]'::jsonb,1,'Opposed engine.','original'),
('127.889.d.2.B',3,'A student traces the intake, compression, power and exhaust strokes through one cylinder. She is:','["describing seats", "avoiding theory", "explaining the operational theory of reciprocating internal combustion aircraft engines", "describing tires"]'::jsonb,2,'Four-stroke cycle.','original'),
('127.889.d.2.B',4,'The spark ignites the fuel-air mixture at the end of the:','["power stroke", "exhaust stroke", "intake stroke", "compression stroke"]'::jsonb,3,'Spark timing.','original'),
('127.889.d.2.C',3,'A mechanic fogs the cylinders with preservative oil and seals the openings on an engine going into storage. She is explaining:','["the purpose and methods of reciprocating engine preservation", "dumping oil", "avoiding storage", "painting the engine"]'::jsonb,0,'Preservation.','original'),
('127.889.d.2.C',4,'Engines are preserved before storage to prevent:','["cleaner exhaust", "corrosion on internal parts", "extra power", "more noise"]'::jsonb,1,'Corrosion.','original'),
('127.889.d.2.D',3,'A student reads about borescope inspections, oil analysis and compression tests as parts of engine upkeep. She is explaining:','["avoiding maintenance", "painting parts", "the purpose and methods of reciprocating engine maintenance and inspection", "ignoring inspection"]'::jsonb,2,'Engine inspection.','original'),
('127.889.d.2.D',4,'An oil analysis can reveal:','["tire wear", "paint color", "fuel brand", "metal wear particles from inside the engine"]'::jsonb,3,'Oil analysis.','original'),
('127.889.d.2.E',3,'A technician looks up the steps to start and run an engine on the ramp, including chocks, a spotter and a fire extinguisher. She is:','["locating and explaining the procedures for reciprocating engine ground operations", "skipping steps", "guessing", "ignoring the manual"]'::jsonb,0,'Ground run.','original'),
('127.889.d.2.E',4,'Before a ground run, the aircraft should be:','["on a cart", "chocked or tied down", "on jacks", "unsecured"]'::jsonb,1,'Chocks.','original'),
('127.889.d.2.F',3,'A student labels the injectors, turbocharger and high-pressure fuel pump of a diesel aircraft engine. She is:','["labeling seats", "labeling tires", "identifying the components and explaining the basic operation of diesel engines", "labeling lights"]'::jsonb,2,'Diesel parts.','original'),
('127.889.d.2.F',4,'A diesel engine does not use:','["a crankshaft", "pistons", "cylinders", "spark plugs"]'::jsonb,3,'No spark plugs.','original'),
('127.889.d.2.G',3,'A student explains how air is compressed until it is hot enough to ignite the injected fuel. She is:','["explaining the basic operational theory of diesel engines", "describing seats", "avoiding theory", "describing tires"]'::jsonb,0,'Compression ignition.','original'),
('127.889.d.2.G',4,'In a diesel engine, fuel ignites because of:','["a glow of paint", "the heat of compressed air", "a magneto", "a spark plug"]'::jsonb,1,'Compression heat.','original'),
('127.889.d.2.H',3,'A student reads why pulling a propeller by hand with the ignition on can start the engine. She is researching:','["paint choices", "tire brands", "the risks of maintenance that requires moving the propeller", "no risks"]'::jsonb,2,'Prop hazard.','original'),
('127.889.d.2.H',4,'Before moving a propeller by hand, the ignition switch should be:','["on", "in ''both''", "in ''start''", "off, with the key removed"]'::jsonb,3,'Hot prop.','original'),
('127.889.d.2.I',3,'A student reads that running a piston engine with the cowling off can overheat it and expose people to moving parts. She is researching:','["the risks of ground operating a reciprocating engine", "no risks", "tire brands", "paint choices"]'::jsonb,0,'Ground run risks.','original'),
('127.889.d.2.I',4,'During ground runs, bystanders should stay away from the propeller arc because the:','["engine cools them", "blades can strike them and blow debris backward", "blades are quiet", "exhaust is cold"]'::jsonb,1,'Prop arc.','original'),
('127.889.d.2.J',3,'A mechanic reviews the steps to take if an engine catches fire on start: keep cranking, shut off fuel and call for help. She is researching:','["paint choices", "tire brands", "the actions necessary in the event of a reciprocating engine fire", "no actions"]'::jsonb,2,'Engine fire response.','original'),
('127.889.d.2.J',4,'If a fire starts in the intake during engine start, a common first action is to:','["open the cowl", "add fuel", "stop cranking", "keep the engine turning to pull the flames into the engine"]'::jsonb,3,'Keep cranking.','original'),
('127.889.d.2.K',3,'A technician ignores the torque value in the manual and tightens a bolt by feel. She is facing:','["the risks of not using the manufacturer''s procedures during maintenance", "better results", "faster service", "no risks"]'::jsonb,0,'Use procedures.','original'),
('127.889.d.2.K',4,'Skipping the manufacturer''s procedure can result in:','["a quieter engine", "engine failure or an unsafe repair", "a better engine", "a lighter engine"]'::jsonb,1,'Skipping steps.','original'),
('127.889.d.3.A',3,'A student checks each cylinder''s walls, valves and head with a borescope and writes down what she sees. She is:','["skipping notes", "ignoring cylinders", "performing and documenting findings from a cylinder assembly inspection", "painting cylinders"]'::jsonb,2,'Cylinder inspection.','original'),
('127.889.d.3.A',4,'Findings from a cylinder inspection should be:','["forgotten", "hidden", "erased", "documented in the maintenance record"]'::jsonb,3,'Document.','original'),
('127.889.d.3.B',3,'A mechanic runs an engine and troubleshoots a rough idle by checking the plugs, magnetos and mixture. She is:','["operating and troubleshooting a reciprocating engine", "painting the engine", "guessing", "ignoring the engine"]'::jsonb,0,'Rough engine.','original'),
('127.889.d.3.B',4,'A big rpm drop on one magneto during a run-up usually points to:','["a bad tire", "a problem with that ignition system or its plugs", "a radio fault", "a seat problem"]'::jsonb,1,'Mag drop.','original'),
('127.889.d.3.C',3,'A student slides the wrist pin through the piston and connecting rod and installs the retaining rings. She is:','["painting a piston", "buying a piston", "installing a wrist pin in a piston", "removing a piston"]'::jsonb,2,'Wrist pin.','original'),
('127.889.d.3.C',4,'The wrist pin connects the piston to the:','["cylinder head", "crankshaft journal", "spark plug", "connecting rod"]'::jsonb,3,'Wrist pin link.','original'),
('127.889.d.3.D',3,'A student points to the cylinder head, barrel, crank throws and main journals on a cut-away engine. She is:','["identifying the parts of a cylinder and a crankshaft", "identifying lights", "identifying tires", "identifying seats"]'::jsonb,0,'Parts.','original'),
('127.889.d.3.D',4,'The crankshaft changes the pistons'' up and down motion into:','["fuel flow", "rotating motion", "lift", "heat"]'::jsonb,1,'Crankshaft job.','original'),
('127.889.d.3.E',3,'A mechanic examines the main bearing shells and connecting rod bearings for scoring and wear. She is:','["skipping inspection", "ignoring bearings", "identifying and inspecting bearings found in reciprocating engines", "painting bearings"]'::jsonb,2,'Bearings.','original'),
('127.889.d.3.E',4,'Metal flakes in the oil filter can mean:','["clean oil", "new oil", "a healthy engine", "a bearing or other part is wearing"]'::jsonb,3,'Metal in oil.','original'),
('127.889.d.3.F',3,'A mechanic checks the throttle cable and the mixture push-pull rod for travel and smooth movement. She is:','["inspecting and rigging cable and push-pull engine controls", "painting controls", "bending cables", "ignoring controls"]'::jsonb,0,'Engine controls.','original'),
('127.889.d.3.F',4,'When rigged correctly, the throttle linkage should allow:','["no travel", "full travel from idle to full power", "half travel", "random travel"]'::jsonb,1,'Full travel.','original'),
('127.889.d.4.A',3,'A student labels the compressor, burner and turbine and compares turbojet, turbofan and turboprop engines. She is:','["labeling lights", "labeling seats", "identifying the components and types of turbine engines", "labeling tires"]'::jsonb,2,'Turbine engines.','original'),
('127.889.d.4.A',4,'A turboprop engine uses its turbine to turn a:','["wheel", "rotor blade only", "fan only", "propeller through a reduction gearbox"]'::jsonb,3,'Turboprop.','original'),
('127.889.d.4.B',3,'A student traces air through intake, compression, combustion, turbine and exhaust. She is:','["explaining the basic operational theory of turbine engines", "describing seats", "avoiding theory", "describing tires"]'::jsonb,0,'Turbine cycle.','original'),
('127.889.d.4.B',4,'In a turbine engine, the turbine section extracts energy to drive the:','["seats", "compressor", "wheels", "fuel tank"]'::jsonb,1,'Turbine drives compressor.','original'),
('127.889.d.4.C',3,'A technician watches EGT, N1, N2 and fuel flow during a ground run. She is:','["ignoring gauges", "painting gauges", "explaining the purpose and methods of monitoring turbine engine performance", "avoiding engines"]'::jsonb,2,'Monitoring.','original'),
('127.889.d.4.C',4,'A rising EGT trend over time may indicate:','["better performance", "less wear", "improved cooling", "engine deterioration or a problem"]'::jsonb,3,'EGT trend.','original'),
('127.889.d.4.D',3,'A technician follows a flow chart to troubleshoot a hot start and schedules the next hot-section inspection. She is:','["explaining the purpose and methods of turbine engine troubleshooting and maintenance", "guessing", "ignoring faults", "skipping inspection"]'::jsonb,0,'Turbine maintenance.','original'),
('127.889.d.4.D',4,'A hot section inspection looks at parts that are exposed to:','["the cabin", "extreme temperatures from combustion", "fuel tanks", "cold air"]'::jsonb,1,'Hot section.','original'),
('127.889.d.4.E',3,'A student researches how dirty compressor blades, eroded turbines and leaking seals reduce performance. She is:','["ignoring losses", "guessing", "researching and explaining the causes of turbine engine performance loss", "painting blades"]'::jsonb,2,'Performance loss.','original'),
('127.889.d.4.E',4,'Compressor blade fouling can reduce:','["engine weight", "cabin noise", "fuel color", "airflow and pressure ratio"]'::jsonb,3,'Fouling.','original'),
('127.889.d.4.F',3,'A student traces bleed air from the compressor to the cabin heat and the anti-ice system. She is:','["explaining the basic operational theory of bleed air systems", "describing tires", "avoiding bleed air", "describing seats"]'::jsonb,0,'Bleed air.','original'),
('127.889.d.4.F',4,'Bleed air is hot, high-pressure air taken from the:','["fuel tank", "compressor section", "tire", "exhaust tailpipe"]'::jsonb,1,'Bleed source.','original'),
('127.889.d.4.G',3,'A mechanic preserves an idle turbine engine by running preservative oil through the fuel system and sealing the inlet and exhaust. She is explaining:','["dumping fuel", "painting the engine", "the purpose and methods of turbine engine preservation", "avoiding storage"]'::jsonb,2,'Turbine preservation.','original'),
('127.889.d.4.G',4,'Sealing the inlet and exhaust of a stored turbine keeps out:','["exhaust", "fuel", "oil", "moisture and foreign objects"]'::jsonb,3,'Seal openings.','original'),
('127.889.d.4.H',3,'A student traces how a small engine in the tail provides power for startup and air conditioning on the ground. She is explaining:','["the theory and application of auxiliary power units", "avoiding APUs", "describing seats", "describing tires"]'::jsonb,0,'APU.','original'),
('127.889.d.4.H',4,'An APU is mainly used to provide:','["fuel", "electrical power and bleed air when the main engines are off", "lift", "wheel braking"]'::jsonb,1,'APU use.','original'),
('127.889.d.4.I',3,'A student learns that standing in front of a turbine inlet while it runs can pull a person in, and the exhaust is a burn hazard. She is researching:','["no risks", "tire brands", "the risks of turbine engine operation", "paint choices"]'::jsonb,2,'Turbine run risks.','original'),
('127.889.d.4.I',4,'A running turbine engine''s inlet is dangerous because it can:','["pull fuel", "hold still", "blow cold air", "suck in people and objects"]'::jsonb,3,'Inlet hazard.','original'),
('127.889.d.4.J',3,'A technician reads that a turbine can stay hot for a long time after shutdown. She is researching:','["the risks of performing maintenance on a turbine engine", "no risks", "paint choices", "tire brands"]'::jsonb,0,'Turbine maintenance risks.','original'),
('127.889.d.4.J',4,'Before working on a recently shut down turbine engine, a mechanic should:','["touch the exhaust", "allow it to cool and lock out the controls", "run it again", "start working at once"]'::jsonb,1,'Cool first.','original'),
('127.889.d.4.K',3,'A mechanic reviews the steps to take in a turbine engine fire on the ramp: shut off fuel, motor the engine and use the extinguisher. She is researching:','["tire brands", "paint choices", "the actions necessary in the event of a turbine engine fire", "no actions"]'::jsonb,2,'Turbine fire.','original'),
('127.889.d.4.K',4,'One action to take in a turbine engine fire is to:','["add fuel", "close the cowling", "start another engine", "shut off the fuel supply"]'::jsonb,3,'Fuel off.','original'),
('127.889.d.4.L',3,'A mechanic is told to walk the ramp for stones, rags and bolts before an engine run. She is researching:','["the risks of foreign object damage (FOD) to turbine engines", "paint choices", "no risks", "tire brands"]'::jsonb,0,'FOD.','original'),
('127.889.d.4.L',4,'A small bolt sucked into a turbine inlet can:','["improve flow", "damage compressor blades", "clean the blades", "cool the engine"]'::jsonb,1,'FOD damage.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
